import{z as B,x as s,o as i,c as p,q as t,j as r,D as l,d as e,s as o,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"KKT 条件","description":"","frontmatter":{"title":"KKT 条件","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/kkt-conditions.md","filePath":"econ/kkt-conditions.md","lastUpdated":1791063341000}'),d={name:"econ/kkt-conditions.md"};function m(u,a,_,g,T,h){const n=s("Mermaid");return i(),p("div",null,[a[2]||(a[2]=t('<h1 id="kkt-条件" tabindex="-1">KKT 条件 <a class="header-anchor" href="#kkt-条件" aria-label="Permalink to &quot;KKT 条件&quot;">​</a></h1><div class="epigraph"><p>不等式把可行方向收成锥；互补松弛说：没顶上的约束，乘子必须为零。</p><footer>—— 据 Boyd and Vandenberghe, Convex Optimization, 第 5 章；Mas-Colell, Whinston and Green 数学附录整理</footer></div><p>上一课<a href="/econ/lagrange-multiplier">拉格朗日乘子</a>处理 \\(h(x)=0\\)。消费非负、产能上限、激励相容里的参与约束，都是不等式。缺口是：有的约束在最优处松弛（乘子应为零），有的绷紧（回到等式乘子）。KKT 把两者写在同一组条件里。本课只补这一块，不重写无约束 FONC，也不把数值求解器讲一遍。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(\\max f(x)\\) s.t. \\(g_i(x)\\le 0\\)、\\(h_j(x)=0\\)。在约束品性（如 Slater：凸问题存在严格可行点；或 LICQ）下，最优 \\(x^*\\) 存在乘子 \\(\\mu\\ge 0\\)、\\(\\lambda\\) 使</p><ol><li>平稳：\\(\\nabla f(x^*)=\\sum_i\\mu_i\\nabla g_i(x^*)+\\sum_j\\lambda_j\\nabla h_j(x^*)\\)（按最大化、约束 \\(\\le 0\\) 的符号书写；最小化则目标梯度变号约定需一致）；</li><li>原可行：\\(g(x^*)\\le 0\\)、\\(h(x^*)=0\\)；</li><li>对偶可行：\\(\\mu\\ge 0\\)；</li><li>互补松弛：\\(\\mu_i g_i(x^*)=0\\)。</li></ol><p>互补松弛是新信息：要么 \\(g_i(x^*)=0\\)（约束生效），要么 \\(\\mu_i=0\\)（影子价格为零）。角点消费 \\(x_k=0\\) 时，该商品的「买更多」方向被挡住，\\(\\partial u/\\partial x_k\\le\\lambda p_k\\)，差用 \\(\\mu_k\\) 补上。后课<a href="/econ/interior-corner">内点与角点</a>直接用这组互补。</p><h3 id="互补不是「两个约束各满足一半」" tabindex="-1">互补不是「两个约束各满足一半」 <a class="header-anchor" href="#互补不是「两个约束各满足一半」" aria-label="Permalink to &quot;互补不是「两个约束各满足一半」&quot;">​</a></h3><p>\\(\\mu_i g_i=0\\) 不是把约束满足到一半。它是逐坐标的择一：松约束的乘子精确为零，紧约束的乘子自由（只非负）。不要读成「平均意义上互补」。Slackness 失败（\\(\\mu_i\\gt 0\\) 且 \\(g_i\\lt 0\\)）在正则问题里不会出现；若数据里看到，多半是约束写反或乘子符号约定乱了。</p><p><span class="marginnote">Slater 对凸问题足够；非凸问题 KKT 可以既不必要也不充分。主干的消费者、成本最小化走凸，一阶当充分用。</span></p><p><span class="marginnote">乘子 \\(\\mu_i\\) 可以翻译成「约束的影子价格」：它回答「把这个约束放松一格，最优值能涨多少」。数字实例：产能上限若松弛一格利润能多 5 元，最优处 \\(\\mu_1=5\\)；产能远没用完的车间 \\(\\mu=0\\)——多给产能白给，这就是松约束乘子为零的含义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把有效约束（最优处取等号的那些 \\(g_i\\)）收成等式，上一课的 Lagrange 作用在这个有效集合上；无效约束的乘子置零。KKT 是对「哪一批约束有效」的事先未知版本：乘子与松紧一起解。</p><p>凸问题（凹目标、凸 \\(g\\)、仿射 \\(h\\)）在 Slater 下：KKT 必要且充分，强对偶成立，最优值等于对偶问题最优值。这是后课成本函数、利润函数可用对偶变量刻画的许可。非凸激励约束（道德风险里的 IC）常常破坏 Slater 与凸，KKT 变成「先写、再验证」，不是自动充分。</p><p><span class="marginnote">为什么 Slater 重要：它要求凸问题里存在一个「严格可行点」——所有不等式都留有余地。看着技术化，实际是许可证：有它，KKT 才从「必要」升级成「必要且充分」，对偶零缺口；没有它，解出来的 KKT 点可能根本不是真最优。</span></p>',15)),(i(),r(A,null,{default:l(()=>[o(n,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20INEQ%5B%22%E4%B8%8D%E7%AD%89%E5%BC%8F%20g%20%E5%B0%8F%E4%BA%8E%E7%AD%89%E4%BA%8E%200%22%5D%20--%3E%20COMP%5B%22%E4%BA%92%E8%A1%A5%EF%BC%9Amu%20%E4%B9%98%20g%20%E7%AD%89%E4%BA%8E%200%22%5D%0A%20%20EQ%5B%22%E7%AD%89%E5%BC%8F%20h%20%E7%AD%89%E4%BA%8E%200%22%5D%20--%3E%20STAT%5B%22%E5%B9%B3%E7%A8%B3%EF%BC%9A%E6%A2%AF%E5%BA%A6%E5%8C%B9%E9%85%8D%22%5D%0A%20%20COMP%20--%3E%20STAT%0A%20%20STAT%20--%3E%20CORNER%5B%22%E8%A7%92%E7%82%B9%EF%BC%9A%E9%83%A8%E5%88%86%20mu%20%E4%B8%BA%E6%AD%A3%22%5D%0A%20%20STAT%20--%3E%20INT%5B%22%E5%86%85%E7%82%B9%EF%BC%9Amu%20%E5%85%A8%E9%9B%B6%EF%BC%8C%E5%9B%9E%E5%88%B0%20Lagrange%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("可行方向锥是：不进入 \\(g_i\\gt 0\\)、不离开 \\(h=0\\) 的方向。最优要求目标在这个锥上不能再升，故 \\(\\nabla f\\) 落在约束梯度的锥组合里——这仍是"),E("a",{href:"/econ/separating-hyperplane"},"分离超平面"),e("的法锥版。\\(\\mu_i\\ge 0\\) 来自不等式的方向性：只能「推向可行一侧」，不能把乘子写成任意实数。")],-1)),a[5]||(a[5]=E("p",null,"内点解全体 \\(g_i\\lt 0\\)，于是全体 \\(\\mu_i=0\\)，KKT 退回无约束或纯等式 Lagrange。所以内点不是另一种理论，是 KKT 的退化。角点是另一退化：若干坐标约束生效。后课画两商品图的切点与轴上端点，就是这两种退化。",-1)),(i(),r(A,null,{default:l(()=>[o(n,{id:"mermaid-72",class:"mermaid",graph:"flowchart%20TD%0A%20%20START%5B%22%E6%8B%BF%E5%88%B0%E5%80%99%E9%80%89%E6%9C%80%E4%BC%98%20x%22%5D%20--%3E%20CHK%7B%22%E6%9C%89%E6%B2%A1%E6%9C%89%E7%BA%A6%E6%9D%9F%E7%BB%B7%E7%B4%A7%22%7D%0A%20%20CHK%20--%3E%7C%22%E5%85%A8%E6%9D%BE%22%7C%20INT%5B%22%E5%86%85%E7%82%B9%3A%20%E5%85%A8%E9%83%A8%20mu%20%E4%B8%BA%E9%9B%B6%22%5D%0A%20%20INT%20--%3E%20NOC%5B%22%E6%A2%AF%E5%BA%A6%E4%B8%BA%E9%9B%B6%2C%20%E5%9B%9E%E5%88%B0%E6%97%A0%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20CHK%20--%3E%7C%22%E9%83%A8%E5%88%86%E7%B4%A7%22%7C%20COR%5B%22%E8%A7%92%E7%82%B9%3A%20%E7%B4%A7%E7%BA%A6%E6%9D%9F%E7%9A%84%20mu%20%E5%8F%AF%E4%B8%BA%E6%AD%A3%22%5D%0A%20%20COR%20--%3E%20TRADE%5B%22%E8%A2%AB%E6%8C%A1%E6%96%B9%E5%90%91%E5%B7%AE%E4%BB%B7%E8%AE%B0%E5%9C%A8%20mu%20%E4%B8%8A%22%5D%0A%20%20NOC%20--%3E%20VAL%5B%22mu%20%E5%B0%B1%E6%98%AF%E5%BD%B1%E5%AD%90%E4%BB%B7%E6%A0%BC%22%5D%0A%20%20TRADE%20--%3E%20VAL%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p><span class="marginnote">互补松弛让包络只对绷紧的约束计数。松掉的资源影子价格为零：再给一单位也绑不到最优值上。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲二次规划算法、有效集法、内点法。也不把 KKT 推广到抽象 Banach 空间的 Lagrange 乘子。互补松弛在离散选择、整数约束上要换成分支，不在主干。下一课问：参数动时，最优<strong>值</strong>怎么变——乘子正是那条导数。</p><p><span class="marginnote">常见误区：把 \\(\\mu_i g_i=0\\) 读成「两条各满足一半」或「平均意义上互补」。它实际是逐条约束上的择一开关：要么绷紧（乘子自由），要么松弛（乘子精确为零）。在结果里看到 \\(\\mu\\gt 0\\) 与 \\(g\\lt 0\\) 并存，多半是符号约定写反了，而不是定理出了例外。</span></p><p>后课默认：带不等式的光滑凸规划，最优写成 KKT；角点用互补松弛读，不把 \\(\\nabla u=\\lambda p\\) 强加在零消费上。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>KKT = 平稳 + 可行 + \\(\\mu\\ge 0\\) + 互补松弛。</li><li>松约束乘子为零；紧约束回到 Lagrange。</li><li>凸加 Slater：必要且充分，并对偶间隙为零。</li><li>内点与角点都是 KKT 的特例，不是另一套理论。</li><li>下一课：<a href="/econ/envelope-theorem">包络定理</a>。</li><li>出处：Boyd and Vandenberghe 第 5 章；MWG 数学附录。</li></ul>',7))])}const K=B(d,[["render",m]]);export{c as __pageData,K as default};
